#!/usr/bin/env bash
# docs-a11y.sh SITE_DIR
#
# The automated accessibility check of the built documentation portal (#20,
# NFR-A11Y-001): every page is loaded in headless Chrome and checked by axe
# (pa11y-ci with the axe runner) against WCAG 2.0, 2.1 and 2.2 level A and AA
# and axe's best practices.
#
# - The guide pages (every page but reference.html, which we write) fail on
#   EVERY axe result: violations of any impact, and results axe could not
#   decide by itself ("needs review", such as a contrast it cannot compute).
# - reference.html is generated by Redoc, which we do not write. Its results
#   are printed as notes, but their count of distinct failures per rule (see
#   the key below) is held against the
#   committed baseline scripts/docs-a11y-baseline.json: a rule above its
#   count, or a rule not in the baseline, fails. A count below it is printed
#   so the baseline can be lowered; scripts/docs-a11y-ratchet.sh refuses a
#   baseline that rises above the pull request base's.
#
# Fails closed: no page, a page that did not load, fewer pages reported than
# the site has, or a report that cannot be read is a failure, never a pass.
#
# The toolchain is pinned by scripts/a11y-tools/package-lock.json and
# installed there with `npm ci --ignore-scripts` (no install script runs, so
# no browser is downloaded; the network is used for the packages only).
# Chrome is the system's: CHROME_PATH, else the first of google-chrome,
# chromium, chromium-browser on PATH, else the macOS application.
#
# DOCS_A11Y_PA11Y replaces the pa11y-ci command (the self-test's stub; it is
# called with --config FILE --json and needs no Chrome). DOCS_A11Y_BASELINE
# replaces the baseline file.
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
site=${1:?usage: docs-a11y.sh SITE_DIR}
baseline=${DOCS_A11Y_BASELINE:-$here/docs-a11y-baseline.json}

site=$(cd "$site" && pwd)
pages=()
while IFS= read -r f; do pages+=("$f"); done < <(find "$site" -maxdepth 1 -name '*.html' -type f | sort)
(( ${#pages[@]} > 0 )) || { echo "FAIL: no page found in $site: refusing to report a clean site" >&2; exit 2; }
jq -e 'type == "object" and all(.[]; type == "object" and all(.[]; type == "number"))' "$baseline" >/dev/null 2>&1 ||
  { echo "FAIL: the baseline $baseline is not readable as {page: {rule: count}}" >&2; exit 2; }

if [[ -n ${DOCS_A11Y_PA11Y:-} ]]; then
  pa11y=("$DOCS_A11Y_PA11Y")
  chrome=${CHROME_PATH:-unused}
else
  tools=$here/a11y-tools
  npm ci --prefix "$tools" --ignore-scripts --no-audit --no-fund --loglevel=error >/dev/null ||
    { echo "FAIL: could not install the pinned toolchain in $tools" >&2; exit 2; }
  pa11y=("$tools/node_modules/.bin/pa11y-ci")
  chrome=${CHROME_PATH:-}
  if [[ -z $chrome ]]; then
    for c in google-chrome chromium chromium-browser; do
      chrome=$(command -v "$c" || true)
      [[ -n $chrome ]] && break
    done
  fi
  [[ -n $chrome ]] || chrome="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
  [[ -x $chrome ]] || { echo "FAIL: no Chrome found; set CHROME_PATH" >&2; exit 2; }
fi

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

# WCAG 2.2 AA: the axe runner (scripts/a11y-tools/axe-runner.js: pa11y's own,
# plus the colours and axe's selector of each result) selects the 2.0 and 2.1 A/AA tags and best
# practices; the 2.2 AA rule is enabled by name.
jq -n --arg chrome "$chrome" --arg runner "$here/a11y-tools/axe-runner.js" '{
  defaults: {
    runners: [$runner],
    standard: "WCAG2AA",
    rules: ["target-size"],
    includeWarnings: true,
    includeNotices: true,
    timeout: 60000,
    chromeLaunchConfig: {executablePath: $chrome, args: ["--no-sandbox", "--disable-dev-shm-usage"]}
  },
  urls: $ARGS.positional
}' --args "${pages[@]/#/file://}" > "$tmp/config.json"

for p in "${pages[@]}"; do echo "docs a11y: found ${p#"$site"/}"; done

set +e
"${pa11y[@]}" --config "$tmp/config.json" --json > "$tmp/report.json" 2> "$tmp/stderr"
status=$?
set -e
jq -e '(.results | type == "object") and all(.results[]; type == "array")' "$tmp/report.json" >/dev/null 2>&1 ||
  { echo "FAIL: pa11y-ci wrote no readable report (exit $status)" >&2; cat "$tmp/stderr" >&2; exit 2; }

# Every page of the site must be in the report, under its own URL.
missing=$(jq -r '.results as $r | $ARGS.positional[] | select(. as $u | $r | has($u) | not)' --args "${pages[@]/#/file://}" < "$tmp/report.json")
if [[ -n $missing ]]; then
  echo "FAIL: pa11y-ci reported $(jq '.results | length' "$tmp/report.json") page(s) of ${#pages[@]}; not reported:" >&2
  while IFS= read -r m; do echo "  ${m#"file://$site/"}" >&2; done <<<"$missing"
  exit 2
fi

# One line per result: page, kind (load, review, or the pa11y type), rule,
# message, selector, and the key of the distinct failure it is. A page that
# could not be loaded is an object with a message and no type.
#
# The key is what reference.html is counted by, so that the example content
# Redoc renders does not move the count: one failure per colour pair for
# color-contrast (fg/bg as axe compared them, "undetermined" when axe could
# not), and for any other rule axe's selector (else pa11y's) with its
# nth-child/nth-of-type parts removed and every number replaced by N, so that
# the tenth row of a table is the same failure as the first.
jq -r --arg site "$site/" '
  def key: if .code == "color-contrast" then
      (if (.runnerExtras.fgColor // null) == null or (.runnerExtras.bgColor // null) == null
       then "undetermined" else "\(.runnerExtras.fgColor)/\(.runnerExtras.bgColor)" end)
    else ((.runnerExtras.target // .selector // "-")
      | gsub(":nth-(last-)?(child|of-type)\\([^)]*\\)"; "") | gsub("[0-9]+"; "N")) end;
  .results | to_entries[] | (.key | sub("^file://"; "") | ltrimstr($site)) as $page | .value[]
  | if (.type == null) then [$page, "load", "-", "could not be checked: \(.message)", "-", "-"]
    else [$page, (if .runnerExtras.needsFurtherReview then "review" else .type end), .code, .message, (.selector // "-"), key] end
  | @tsv' "$tmp/report.json" > "$tmp/issues.tsv"

fails=0
fail() { echo "FAIL: $*" >&2; fails=$((fails + 1)); }

# Load failures and guide-page results fail.
while IFS=$'\t' read -r page kind rule message selector _key; do
  if [[ $kind == load ]]; then
    fail "$page: $message"
  elif [[ $page != reference.html ]]; then
    fail "$page: $rule ($kind): $message [$selector]"
  fi
done < "$tmp/issues.tsv"

# reference.html: notes, held per rule against the baseline, counted as
# distinct failures (rule x key), not as results.
awk -F'\t' '$1 == "reference.html" && $2 != "load" { print $3 "\t" $6 }' "$tmp/issues.tsv" | sort -u |
  cut -f1 | uniq -c | awk '{ print $2 "\t" $1 }' > "$tmp/reference.tsv"
results=$(awk -F'\t' '$1 == "reference.html" && $2 != "load"' "$tmp/issues.tsv" | wc -l | tr -d ' ')
notes=0
while IFS=$'\t' read -r rule count; do
  notes=$((notes + count))
  allowed=$(jq -r --arg r "$rule" '.["reference.html"][$r] // -1' "$baseline")
  if (( allowed < 0 )); then
    fail "reference.html: $rule: $count distinct failure(s), a rule not in the baseline"
  elif (( count > allowed )); then
    fail "reference.html: $rule: $count distinct failure(s), above the baseline of $allowed"
  elif (( count < allowed )); then
    echo "note: reference.html: $rule: $count distinct failure(s), below the baseline of $allowed: lower it"
  else
    echo "note: reference.html: $rule: $count distinct failure(s), the baseline"
  fi
done < "$tmp/reference.tsv"

if (( fails > 0 )); then
  echo "FAIL: $fails finding(s) over ${#pages[@]} page(s)" >&2
  exit 1
fi
echo "docs a11y: ${#pages[@]} page(s) checked, 0 findings on the guide pages; reference.html: $notes distinct failure(s) ($results result(s)) within the baseline"
